UTextBlock* UCoIPlayerHUD::Text(UPanelWidget* Parent,const FString& Value,int32 Size,bool Gold){auto* T=WidgetTree->ConstructWidget<UTextBlock>();T->SetFont(FCoreStyle::GetDefaultFontStyle("Regular",Size));T->SetColorAndOpacity(Gold?Brass:Paper);T->SetText(FText::FromString(Display::Name(Value)));T->SetAutoWrapText(true);if(Parent)Add(Parent,T);return T;}
