UHorizontalBox* UCoIPlayerHUD::Row(UPanelWidget* Parent){auto* R=WidgetTree->ConstructWidget<UHorizontalBox>();if(Parent)Add(Parent,R);return R;}
UCoIActionButton* UCoIPlayerHUD::Button(UPanelWidget* Parent,const FString& Label,const FString& Key,bool Accent,const FString& Tip){auto* B=WidgetTree->ConstructWidget<UCoIActionButton>();B->OwnerHUD=this;B->Action=Key;auto* T=Text(nullptr,Label,12);B->SetContent(T);B->SetToolTipText(FText::FromString(Tip.IsEmpty()?Label:Tip));FButtonStyle S=FCoreStyle::Get().GetWidgetStyle<FButtonStyle>(TEXT("Button"));S.Normal.TintColor=FSlateColor(Accent?FLinearColor(.25f,.20f,.12f):FLinearColor(.085f,.105f,.11f));S.Hovered.TintColor=FSlateColor(FLinearColor(.27f,.29f,.25f));S.Pressed.TintColor=FSlateColor(Brass);S.NormalPadding=FMargin(12,7);B->SetStyle(S);if(Parent){Add(Parent,B);if(auto* Cell=Cast<UHorizontalBoxSlot>(B->Slot))Cell->SetPadding(FMargin(0,0,8,0));}return B;}
UBorder* UCoIPlayerHUD::Surface(const FVector2D& Pos,const FVector2D& Size){auto* B=WidgetTree->ConstructWidget<UBorder>();B->SetBrushColor(Ink);B->SetPadding(FMargin(12,8));auto* S=Root->AddChildToCanvas(B);S->SetPosition(Pos);S->SetSize(Size);return B;}
UComboBoxString* UCoIPlayerHUD::Choice(UPanelWidget* Parent,const FString& Key,const FString& Label,const TArray<TPair<FString,FString>>& Options,const FString& Default){auto* Box=WidgetTree->ConstructWidget<UVerticalBox>();Add(Parent,Box);if(auto* Cell=Cast<UHorizontalBoxSlot>(Box->Slot)){Cell->SetSize(FSlateChildSize(ESlateSizeRule::Fill));Cell->SetPadding(FMargin(0,0,12,0));}Text(Box,Label,11,true);auto* C=WidgetTree->ConstructWidget<UCoIChoice>();C->SetMaxListHeight(250);Add(Box,C);Choices.Add(Key,C);ChoiceValues.Add(Key,{});for(const auto& Pair:Options){FString Display=CoISim::Display::Name(Pair.Value);while(ChoiceValues[Key].Contains(Display))Display+=TEXT(" ");C->AddOption(Display);ChoiceValues[Key].Add(Display,Pair.Key);if(Pair.Key==Default)C->SetSelectedOption(Display);}if(C->GetSelectedOption().IsEmpty()&&Options.Num())C->SetSelectedIndex(0);Selected.Add(Key,ChoiceValues[Key].FindRef(C->GetSelectedOption()));C->OnSelectionChanged.AddDynamic(this,&UCoIPlayerHUD::ChoiceChanged);C->SetToolTipText(FText::FromString(Label));return C;}
void UCoIPlayerHUD::Field(UPanelWidget* Parent,const FString& Key,const FString& Label,const FString& Value){auto* Box=WidgetTree->ConstructWidget<UVerticalBox>();Add(Parent,Box);if(auto* Cell=Cast<UHorizontalBoxSlot>(Box->Slot)){Cell->SetSize(FSlateChildSize(ESlateSizeRule::Fill));Cell->SetPadding(FMargin(0,0,12,0));}Text(Box,Label,11,true);auto* F=WidgetTree->ConstructWidget<UEditableTextBox>();auto Style=F->GetWidgetStyle();Style.SetFont(FCoreStyle::GetDefaultFontStyle("Regular",14));Style.TextStyle.SetColorAndOpacity(Ink);Style.SetForegroundColor(Ink).SetFocusedForegroundColor(Ink);F->SetWidgetStyle(Style);int64 Raw=0;const bool USD=Display::IsMoneyField(Key);F->SetText(FText::FromString((USD||Display::IsMarkupField(Key))&&LexTryParseString(Raw,*Value)?(USD?Display::MoneyInput(Raw):Display::MarkupInput(Raw)):Value));F->SetToolTipText(FText::FromString(Label+(Display::IsMarkupField(Key)?TEXT(" — Aufschlag in Prozent, maximal eine Nachkommastelle"):USD?TEXT(" — USD, maximal zwei Nachkommastellen; Komma oder Punkt, ohne Tausendertrennzeichen"):TEXT(" — nur ganze Zahlen"))));Add(Box,F);Fields.Add(Key,F);F->OnTextChanged.AddDynamic(this,&UCoIPlayerHUD::InputChanged);}
