void UCoIPlayerHUD::ChoiceChanged(FString,ESelectInfo::Type){if(Updating)return;const FString PreviousStock=Id(TEXT("form.stock"));for(const auto& Pair:Choices)Selected.Add(Pair.Key,ChoiceValues[Pair.Key].FindRef(Pair.Value->GetSelectedOption()));if(DialogKind==TEXT("haul")&&PreviousStock!=Id(TEXT("form.stock"))&&Sim){Updating=true;const auto& P=Sim->GetSnapshot().Player;const auto* Stock=Find(P.Stocks,Id(TEXT("form.stock")));if(auto* Combo=Choices.FindRef(TEXT("form.target")).Get()){const FString OldTarget=Id(TEXT("form.target"));Combo->ClearOptions();ChoiceValues[TEXT("form.target")].Reset();auto Option=[&](const FString& Key,const FString& Label){Combo->AddOption(Label);ChoiceValues[TEXT("form.target")].Add(Label,Key);if(Key==OldTarget)Combo->SetSelectedOption(Label);};Option(TEXT(""),TEXT("Ziel wählen"));for(const auto& W:P.Stores)if(W.Own||W.Public||(Stock&&W.AcceptedGoods.Contains(Stock->GoodId)))Option(W.Id,W.Name);if(Combo->GetSelectedOption().IsEmpty())Combo->SetSelectedIndex(0);Selected.Add(TEXT("form.target"),ChoiceValues[TEXT("form.target")].FindRef(Combo->GetSelectedOption()));}Updating=false;}
 if(DialogKind.IsEmpty()&&!CityContext.IsEmpty()&&Id(TEXT("hub.city"))!=CityContext){const FString Tab=CityTab;OpenCity(Id(TEXT("hub.city")));Action(TEXT("cityTab|")+Tab);return;}
 RefreshMap();RefreshSelection();if(DialogKind.IsEmpty())RefreshTable();else {ValidDraft=false;if(ConfirmButton)ConfirmButton->SetIsEnabled(false);if(FormState)FormState->SetText(FText::FromString(TEXT("Auswahl geändert. Vorschau aktualisieren.")));}}
void UCoIPlayerHUD::InputChanged(const FText&){ValidDraft=false;if(ConfirmButton)ConfirmButton->SetIsEnabled(false);if(FormState)FormState->SetText(FText::FromString(TEXT("Eingabe geändert. Vorschau aktualisieren.")));}
bool UCoIPlayerHUD::ReadPositive(const FString& Key,int64& N,bool Zero) const {auto* F=Fields.FindRef(Key).Get();if(!F)return false;FString T=F->GetText().ToString();if(Display::IsMarkupField(Key))return Display::ParseMarkupInput(T,N);if(Display::IsMoneyField(Key))return Display::ParseMoneyInput(T,N,Zero);if(T.IsEmpty()||T.Len()>12)return false;for(TCHAR C:T)if(C<TEXT('0')||C>TEXT('9'))return false;return LexTryParseString(N,*T)&&(Zero?N>=0:N>0);}

