void UCoIPlayerHUD::Confirm(){if(Sim&&ValidDraft&&(DialogKind==TEXT("save")||DialogKind==TEXT("load"))){const bool Loading=DialogKind==TEXT("load");const int32 SaveIndex=FCString::Atoi(*ContextId);ValidDraft=false;ConfirmButton->SetIsEnabled(false);FString Error;bool OK=Loading?Sim->LoadSlot(SaveIndex,Error):Sim->SaveSlot(SaveIndex,Error);if(OK){CloseDialog();LastStatus=Loading?TEXT("Spielstand geladen. Partie pausiert; Start setzt sie fort."):TEXT("Spielstand erfolgreich gespeichert.");BuildView(TEXT("Spielstände"));Refresh();}else if(FormState){FormState->SetText(FText::FromString(Error));ValidDraft=true;if(ConfirmButton)ConfirmButton->SetIsEnabled(true);}return;}if(!ValidDraft||PendingTicket||!Sim)return;ValidDraft=false;ConfirmButton->SetIsEnabled(false);int64 Ticket=0;FString Error;if(!Sim->SubmitPlayer(Draft,Token,Ticket,Error)){FormState->SetText(FText::FromString(Error));return;}PendingTicket=Ticket;LastStatus=TEXT("Auftrag gesendet; Umsetzung beim nächsten Simulationsschritt. Bei Pause Start drücken.");FormState->SetText(FText::FromString(LastStatus));NoticeText->SetText(FText::FromString(LastStatus));Notices->SetVisibility(ESlateVisibility::Visible);}
void UCoIPlayerHUD::CloseDialog(){DialogKind.Empty();ContextId.Empty();FormPreview=nullptr;FormState=nullptr;ConfirmButton=nullptr;Fields.Reset();ValidDraft=false;if(Dialog)Dialog->SetVisibility(ESlateVisibility::Collapsed);if(ModalShade)ModalShade->SetVisibility(ESlateVisibility::Collapsed);TArray<FString> Keys;Choices.GetKeys(Keys);for(const auto& K:Keys)if(K.StartsWith(TEXT("form."))){Choices.Remove(K);ChoiceValues.Remove(K);Selected.Remove(K);}}

